def classify_encoding(s):
    if not s:
        return 'unknown'
    base64_chars = set('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=')
    hex_chars = set('0123456789abcdefABCDEF')
    is_base64 = set(s).issubset(base64_chars) and len(s) % 4 == 0
    is_hex = set(s).issubset(hex_chars) and len(s) % 2 == 0
    if is_base64 and not is_hex:
        return 'base64'
    elif is_hex and not is_base64:
        return 'hex'
    elif is_base64 and is_hex:
        # Prefer base64 if it contains base64‑specific chars
        if any(c in '+/=' for c in s):
            return 'base64'
        # Otherwise, it's ambiguous; could be hex only, but base64 also fits
        return 'base64'
    else:
        return 'unknown'
